import { Object3D, Mesh, PlaneGeometry, RepeatWrapping, LinearFilter, MeshBasicNodeMaterial, Texture } from 'three/webgpu';
import { gsap } from 'gsap';
import { flyThrough } from '@/primitives';
import { fontAtlas } from '@/text';

export default function createNode(config, ctx) {
  // Create container
  const root = new Object3D();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Plane dimensions
  const PLANE_WIDTH = 7.0;
  const PLANE_HEIGHT = 0.35;

  // Build ticker text string (joined with gaps)
  const entries = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18'
  ];

  // Text style according to design token
  const textStyle = {
    family: 'JetBrains Mono',
    size: 13,
    weight: 700,
    letterSpacing: 0.06,
    lineHeight: 1,
    fillStyle: '#e8ecf2', // paper color
    // extra spacing between entries (2 * base unit = 0.5 scene units)
    // We'll translate scene units to pixel spacing later based on canvas size.
  };

  // Create offscreen canvas for the ticker texture
  const dpi = window.devicePixelRatio || 1;
  const baseUnitPixels = 64; // arbitrary pixel size for base unit (0.25 scene units)
  const gapPixels = baseUnitPixels * 2; // 0.5 scene units gap

  // First, measure text width using a temporary canvas
  const measureCanvas = new OffscreenCanvas(2, 2);
  const measureCtx = measureCanvas.getContext('2d');
  measureCtx.font = `${textStyle.weight} ${textStyle.size}px ${textStyle.family}`;
  const entryWidths = entries.map(e => measureCtx.measureText(e).width);
  const totalWidth = entryWidths.reduce((a, b) => a + b, 0) + gapPixels * (entries.length - 1);

  // Double the width for seamless loop
  const textureWidth = Math.ceil(totalWidth * 2);
  const textureHeight = Math.ceil(textStyle.size * 2); // enough height for the glyphs

  const canvas = new OffscreenCanvas(textureWidth, textureHeight);
  const ctx2d = canvas.getContext('2d');

  // Render background (transparent)
  ctx2d.clearRect(0, 0, textureWidth, textureHeight);

  // Render text entries twice
  let x = 0;
  const renderSequence = (seq) => {
    for (let i = 0; i < entries.length; i++) {
      const txt = entries[i];
      ctx2d.fillStyle = textStyle.fillStyle;
      ctx2d.font = `${textStyle.weight} ${textStyle.size}px ${textStyle.family}`;
      ctx2d.textBaseline = 'middle';
      const w = entryWidths[i];
      ctx2d.fillText(txt, x, textureHeight / 2);
      x += w + gapPixels;
    }
  };
  renderSequence();
  renderSequence(); // duplicate for seamless loop

  const tickerTexture = new Texture(canvas);
  tickerTexture.wrapS = RepeatWrapping;
  tickerTexture.wrapT = RepeatWrapping;
  tickerTexture.minFilter = LinearFilter;
  tickerTexture.magFilter = LinearFilter;
  tickerTexture.needsUpdate = true;

  // Create edge fade mask texture
  const maskCanvas = new OffscreenCanvas(textureWidth, textureHeight);
  const maskCtx = maskCanvas.getContext('2d');
  const grad = maskCtx.createLinearGradient(0, 0, textureWidth, 0);
  const fadePortion = 0.09 * textureWidth; // corresponds to 0.09 UV
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(fadePortion / textureWidth, 'rgba(0,0,0,1)');
  grad.addColorStop(1 - fadePortion / textureWidth, 'rgba(0,0,0,1)');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  maskCtx.fillStyle = grad;
  maskCtx.fillRect(0, 0, textureWidth, textureHeight);

  const maskTexture = new Texture(maskCanvas);
  maskTexture.wrapS = RepeatWrapping;
  maskTexture.wrapT = RepeatWrapping;
  maskTexture.minFilter = LinearFilter;
  maskTexture.magFilter = LinearFilter;
  maskTexture.needsUpdate = true;

  // Plane geometry and material
  const geometry = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
  const material = new MeshBasicNodeMaterial({
    map: tickerTexture,
    alphaMap: maskTexture,
    transparent: true,
    depthWrite: false,
    color: 0x111117 // surface albedo
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  root.add(mesh);

  // Apply cinematic primitive
  if (ctx.primitives && typeof ctx.primitives['fly-through'] === 'function') {
    ctx.primitives['fly-through'](mesh, { depthUnits: 0, speed: 0.4 });
  } else {
    // fallback: simple GSAP offset animation
    const timeline = gsap.timeline({ repeat: -1, ease: 'none' });
    timeline.to(tickerTexture.offset, {
      x: - (totalWidth / textureWidth),
      duration: (totalWidth / 0.4) / 60, // approximate based on speed (scene units per sec) and pixel scaling
      ease: 'none'
    });
    mesh.userData._timeline = timeline;
  }

  // Handlers placeholder
  root.userData.handlers = {};

  // Cleanup
  root.userData.cleanup = () => {
    geometry.dispose();
    material.map?.dispose();
    material.alphaMap?.dispose();
    material.dispose();
    if (mesh.userData._timeline) {
      mesh.userData._timeline.kill();
    }
  };

  // Apply any additional cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(p => {
      const fn = ctx.primitives?.[p.name];
      if (typeof fn === 'function') {
        fn(mesh, p.params);
      }
    });
  }

  // Render text via fontAtlas (ensure texture is kept alive)
  if (ctx.fontAtlas && typeof ctx.fontAtlas.registerTexture === 'function') {
    ctx.fontAtlas.registerTexture(tickerTexture);
    ctx.fontAtlas.registerTexture(maskTexture);
  }

  return root;
}
